  ...Interactive.transformSchema,
} as const satisfies InteractivitySchema;

const ELEMENT_PROP_KEYS = new Set(["theme","symbol","headline","headline2","levelLabel","price","prevHigh","fontWeight","accent","fontFamily","ink","background","scale","delay","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  theme: "dark",
  symbol: "RMCN",
  headline: "All-time",
  headline2: "high",
  levelLabel: "PREV HIGH",
  price: 128.4,
  prevHigh: 112,
  fontWeight: 500,
  accent: "#3B5BFD",
  fontFamily: "Barlow Condensed",
  scale: 1,
  delay: 0,
  speed: 1,
};

type CandleRallyElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof CandleRallyBase>;

const CandleRallyInner = forwardRef<
  HTMLDivElement,
  CandleRallyElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<CandleRally>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <CandleRallyBase
          {...(componentProps as unknown as ComponentProps<typeof CandleRallyBase>)}
        />
      </div>
    </Sequence>
  );
});

export const CandleRally = Interactive.withSchema({
  Component: CandleRallyInner,
  componentName: "<CandleRally>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});
